from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];D=R/'dist';items=json.loads((D/'data/gallery.json').read_text());esc=lambda s:html.escape(s,quote=True)
header='''<header class="header"><a class="brand" href="index.html"><img src="assets/ht-logo.png" width="46" height="46" alt=""><span>HUMANITARIAN<br><b>TRACKER</b></span></a><nav aria-label="Main navigation"><a href="index.html">Home</a><a href="index.html#about">About</a><a href="index.html#team">Team</a><a href="gallery.html" aria-current="page">Gallery</a><a href="archive.html">Archive</a></nav></header>'''
cards=''.join(f'<a class="photo-card" href="assets/{esc(item["file"])}" data-photo data-index="{i}"><img src="assets/{esc(item["file"])}" alt="{esc(item["alt"])}" width="1200" height="800" loading="lazy"><span aria-hidden="true">↗</span></a>' for i,item in enumerate(items))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Photos from Humanitarian Tracker community events."><title>Gallery | Humanitarian Tracker</title><link rel="icon" href="assets/ht-logo.png"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="archive.css"><link rel="stylesheet" href="gallery.css"><script src="gallery.js" defer></script></head><body class="library-page"><a class="skip" href="#main">Skip to content</a>'''+header+'''<main id="main"><section class="library-hero section gallery-hero"><h1>Community<br><em>in focus</em></h1></section><section class="section photo-section"><h2>Damascus · August 2025</h2><div class="photo-grid">'''+cards+'''</div><button id="more-photos" class="show-more" hidden>Show more photos ↓</button></section></main><footer><a class="brand" href="index.html"><img src="assets/ht-logo.png" width="46" height="46" alt=""><span>HUMANITARIAN<br><b>TRACKER</b></span></a><a href="index.html">Back to the mosaic ↗</a><a href="archive.html">Archive ↗</a><small>© 2026 Humanitarian Tracker · Website by Spotlight</small></footer><dialog id="photo-viewer"><button id="close-photo" aria-label="Close photo">✕</button><img id="viewer-image" alt=""><p id="viewer-caption"></p><div class="viewer-controls"><button id="previous-photo" aria-label="Previous photo">←</button><a id="open-photo" target="_blank" rel="noopener noreferrer">Open photo ↗</a><button id="next-photo" aria-label="Next photo">→</button></div></dialog></body></html>'''
(D/'gallery.html').write_text(page)
print('Gallery generated:',len(items),'local photos')
